<?php
namespace App\Http\Controllers;
use App\Models\User;use Illuminate\Http\Request;use Illuminate\Support\Facades\Auth;use Illuminate\Support\Facades\Hash;use Illuminate\Validation\ValidationException;use Illuminate\View\View;use Illuminate\Http\RedirectResponse;
class AuthController extends Controller {public function showLogin():View{return view('auth.login');}public function login(Request $r):RedirectResponse{$credentials=$r->validate(['email'=>'required|email','password'=>'required|string']);if(!Auth::attempt($credentials,$r->boolean('remember')))throw ValidationException::withMessages(['email'=>'These credentials do not match our records.']);$r->session()->regenerate();return redirect()->intended(route('dashboard'));}public function showRegister():View{return view('auth.register');}public function register(Request $r):RedirectResponse{$data=$r->validate(['name'=>'required|string|max:160','email'=>'required|email|max:255|unique:users,email','password'=>'required|string|min:10|confirmed']);$user=User::create(['name'=>$data['name'],'email'=>$data['email'],'password'=>Hash::make($data['password'])]);Auth::login($user);$r->session()->regenerate();return redirect()->route('dashboard');}public function logout(Request $r):RedirectResponse{Auth::logout();$r->session()->invalidate();$r->session()->regenerateToken();return redirect()->route('login');}}
